  "あのう、これ、コーヒーです。どうぞ。": "/assets/audio/a_115d8a846095137d.m4a",
  "あのう、そちらまでどうやって行きますか。": "/assets/audio/a_1acf517aae0f52d5.m4a",
  "あのう、ナンプラー、ありますか。": "/assets/audio/a_e773d27369b58ce7.m4a",
  "あのう、途中でやめたい場合は？": "/assets/audio/a_8c57e97568f6543b.m4a",
  "あのう、来月7日から10日ほど休みを取らせていただけませんか。": "/assets/audio/a_7c44d57b871f4ace.m4a",
  "あの歌手は人気があります。": "/assets/audio/a_1a51bfea3f16eba6.m4a",
  "あの花屋の前で止めてください。": "/assets/audio/a_23fdfabbb8e66127.m4a",
  "あの漢字は何と読むんですか。": "/assets/audio/a_1efc20c0b16bbe9b.m4a",
  "あの漢字は何と読むんですか。……「きんえん」です。たばこを吸ってはいけないという意味です。": "/assets/audio/a_73ea4462be0aa1b0.m4a",
  "あの歯医者は上手です。": "/assets/audio/a_7268085d8693e77a.m4a",
  "あの新しい靴屋はいい靴がたくさんありますよ。……そうですか。安かったら、買いたいです。": "/assets/audio/a_bef856fde0a6b324.m4a",
  "あの人": "/assets/audio/a_ceda61e90d802492.m4a",
  "あの人はエンジニアです。": "/assets/audio/a_17ecb9a524f29e4d.m4a",
  "あの人はどなたですか。": "/assets/audio/a_ad968799ae50f0f9.m4a",
  "あの人はまだ若いです。": "/assets/audio/a_71ea603af49edb6d.m4a",
  "あの人はミラーさんです。": "/assets/audio/a_37a5720eb5c9230b.m4a",
